        self.items.append(Item(sku=sku, price=price, quantity=quantity))

    def remove_item(self, sku: str):
        self.items = [item for item in self.items if item.sku != sku]

    def clear(self):
        self.items = []

    @property
    def total(self) -> Decimal:
        """Returns the total price of all items in the cart as a Decimal."""
        return sum((item.price * item.quantity for item in self.items), Decimal('0.00'))

    def get_summary(self) -> Dict:
        return {
            "item_count": sum(item.quantity for item in self.items),
            "total": self.total,
            "currency": "EUR"
        }
